ALTER TABLE "account_audit_logs" DROP CONSTRAINT "account_audit_logs_action_check", ADD CONSTRAINT "account_audit_logs_action_check" CHECK (("action" IN ('ACCOUNT_CREATED', 'ACCOUNT_UPDATED', 'ACCOUNT_ARCHIVED', 'PASSWORD_RESET', 'PERIOD_CREATED', 'PERIOD_EXTENDED', 'PERIOD_ASSIGNED') AND "actor_user_id" IS NOT NULL) OR ("action" = 'SYSTEM_ADMIN_BOOTSTRAPPED' AND "actor_user_id" IS NULL));